package e.e.a;
import org.json.*;import java.util.*;
final class RankingCatalog190 {
 static JSONArray restore(JSONArray saved,JSONArray presets)throws JSONException{LinkedHashMap<String,String> names=new LinkedHashMap<>();for(String[] g:RankingRules190.GENRES)names.put(g[0],g[1]);for(int i=0;i<presets.length();i++){JSONObject p=presets.optJSONObject(i);if(p!=null&&!p.optString("id").isEmpty())names.put("custom-"+p.optString("id"),p.optString("name"));}JSONArray out=new JSONArray();Set<String> seen=new HashSet<>();for(int i=0;i<saved.length();i++){JSONObject g=saved.optJSONObject(i);if(g!=null&&names.containsKey(g.optString("id"))&&seen.add(g.optString("id")))out.put(new JSONObject().put("id",g.getString("id")).put("name",names.get(g.getString("id"))).put("visible",g.optBoolean("visible",true)));}for(Map.Entry<String,String> e:names.entrySet())if(seen.add(e.getKey()))out.put(new JSONObject().put("id",e.getKey()).put("name",e.getValue()).put("visible",true));return out;}
 static JSONArray without(JSONArray source,Set<String> ids){JSONArray out=new JSONArray();for(int i=0;i<source.length();i++){JSONObject p=source.optJSONObject(i);if(p!=null&&!ids.contains(p.optString("id")))out.put(p);}return out;}
 static JSONArray move(JSONArray source,String moving,String target,boolean after){if(moving.equals(target))return source;JSONObject item=null;ArrayList<JSONObject> items=new ArrayList<>();int targetIndex=-1;for(int i=0;i<source.length();i++){JSONObject p=source.optJSONObject(i);if(p==null)continue;if(moving.equals(p.optString("id")))item=p;else items.add(p);}if(item==null)return source;for(int i=0;i<items.size();i++)if(target.equals(items.get(i).optString("id")))targetIndex=i;if(targetIndex<0)return source;items.add(targetIndex+(after?1:0),item);JSONArray out=new JSONArray();for(JSONObject p:items)out.put(p);return out;}
 static int offset(int page){return Math.max(0,Math.min(10,page)-1)*100;}
 static boolean ended(int offset,int size,int total){return size<100||offset+size>=Math.min(1000,total);}
}
